-- Restores the 61 NI product rows changed by exseed-product-copy-2026-11-03.sql
begin;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>SULFATE FREE CLEANSER</strong>: Gently cleanse away dirt, oil, and makeup with a luxurious sulfate-free lather loaded with skin-loving botanicals and nutrient-rich ExSeed® Antioxidant Complex. Our moisturizing formula protects the skin’s natural moisture barrier with plant-based ingredients that condition as they clean and is so gentle you can even use it on your face!</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Provence-inspired Lavender mingles with delicate layers of Lemon Blossom and the sweetly seductive scent of sensual Ylang. A soft, comforting fragrance that relaxes your mind and soothes your spirit.</li><li><strong>KEY INGREDIENTS</strong>: Shea butter, Coconut Oil, Vitamin E, and ExSeed®, our antioxidant blend of Cranberry, Carrot, Black Cumin, Grape, and Pomegranate seed oils.</li><li><strong>EXSEED® ANTIOXIDANT COMPLEX</strong>: ExSeed® combines sustainably sourced seed oils from Black Cumin, Cranberry, Raspberry, Grape, and Carrot seeds to replenish, moisturize and protect skin. These phytonutrient seed oils are extracted using a patented, cold-press process to preserve the powerful antioxidant benefits of the seeds for maximum skin benefits.</li><li><strong>100% FREE FROM</strong>: Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$100-00-02$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>SULFATE FREE CLEANSER</strong>: Gently cleanse away dirt, oil, and makeup with a luxurious sulfate-free lather loaded with skin-loving botanicals and nutrient-rich ExSeed® Antioxidant Complex. Our moisturizing formula protects the skin’s natural moisture barrier with plant-based ingredients that condition as they clean and is so gentle you can even use it on your face!</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: An uplifting medley of intoxicating citruses with sweet Bergamot, juicy Orange, fresh Lemon and crisp, ruby red Grapefruit. A clean, classic essence that is positively addicting!</li><li><strong>KEY INGREDIENTS</strong>: Shea butter, Coconut Oil, Vitamin E, and ExSeed®, our antioxidant blend of Cranberry, Carrot, Black Cumin, Grape, and Pomegranate seed oils.</li><li><strong>EXSEED® ANTIOXIDANT COMPLEX</strong>: ExSeed® combines sustainably sourced seed oils from Black Cumin, Cranberry, Raspberry, Grape, and Carrot seeds to replenish, moisturize and protect skin. These phytonutrient seed oils are extracted using a patented, cold-press process to preserve the powerful antioxidant benefits of the seeds for maximum skin benefits.</li><li><strong>100% FREE FROM</strong>: Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$100-00-04$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>SULFATE FREE CLEANSER</strong>: Gently cleanse away dirt, oil, and makeup with a luxurious sulfate-free lather loaded with skin-loving botanicals and nutrient-rich ExSeed® Antioxidant Complex. Our moisturizing formula protects the skin’s natural moisture barrier with plant-based ingredients that condition as they clean and is so gentle you can even use it on your face!</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: A delightfully crisp blend of Agave nectar combines with fragrance notes of fresh Citrus, delicate Pear and uplifting essential oils. A delectable fragrance that will leave your skin deliciously scented.</li><li><strong>KEY INGREDIENTS</strong>: Shea butter, Coconut Oil, Vitamin E, and ExSeed®, our antioxidant blend of Cranberry, Carrot, Black Cumin, Grape, and Pomegranate seed oils.</li><li><strong>EXSEED® ANTIOXIDANT COMPLEX</strong>: ExSeed® combines sustainably sourced seed oils from Black Cumin, Cranberry, Raspberry, Grape, and Carrot seeds to replenish, moisturize and protect skin. These phytonutrient seed oils are extracted using a patented, cold-press process to preserve the powerful antioxidant benefits of the seeds for maximum skin benefits.</li><li><strong>100% FREE FROM</strong>: Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$100-00-07$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>SULFATE FREE CLEANSER</strong>: Gently cleanse away dirt, oil, and makeup with a luxurious sulfate-free lather loaded with skin-loving botanicals and nutrient-rich ExSeed® Antioxidant Complex. Our moisturizing formula protects the skin’s natural moisture barrier with plant-based ingredients that condition as they clean and is so gentle you can even use it on your face!</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Indulge in a seductive blend of creamy Coconut, warm Madagascar Vanilla, and soft Amber. Pure essential oils of Mandarin and Iris meld with the soft undertones of Sandalwood to create an exotic fragrance that is warm, sensual and enticing.</li><li><strong>KEY INGREDIENTS</strong>: Shea butter, Coconut Oil, Vitamin E, and ExSeed®, our antioxidant blend of Cranberry, Carrot, Black Cumin, Grape, and Pomegranate seed oils.</li><li><strong>EXSEED® ANTIOXIDANT COMPLEX</strong>: ExSeed® combines sustainably sourced seed oils from Black Cumin, Cranberry, Raspberry, Grape, and Carrot seeds to replenish, moisturize and protect skin. These phytonutrient seed oils are extracted using a patented, cold-press process to preserve the powerful antioxidant benefits of the seeds for maximum skin benefits.</li><li><strong>100% FREE FROM</strong>: Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$100-00-06$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>SULFATE FREE CLEANSER</strong>: Gently cleanse away dirt, oil, and makeup with a luxurious sulfate-free lather loaded with skin-loving botanicals and nutrient-rich ExSeed® Antioxidant Complex. Our moisturizing formula protects the skin’s natural moisture barrier with plant-based ingredients that condition as they clean and is so gentle you can even use it on your face!</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: An intoxicating scent of fresh cypress, eucalyptus + crisp fir leave your skin soft, smooth + deliciously fragranced.</li><li><strong>KEY INGREDIENTS</strong>: Shea butter, Coconut Oil, Vitamin E, and ExSeed®, our antioxidant blend of Cranberry, Carrot, Black Cumin, Grape, and Pomegranate seed oils.</li><li><strong>EXSEED® ANTIOXIDANT COMPLEX</strong>: ExSeed® combines sustainably sourced seed oils from Black Cumin, Cranberry, Raspberry, Grape, and Carrot seeds to replenish, moisturize and protect skin. These phytonutrient seed oils are extracted using a patented, cold-press process to preserve the powerful antioxidant benefits of the seeds for maximum skin benefits.</li><li><strong>100% FREE FROM</strong>: Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$100-00-08$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned.</p><p>A revitalizing, long-lasting moisture treatment with the seductive scent of creamy Coconut, warm Madagascar Vanilla and sweet Amber leave your skin feeling soft + soothed.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN</strong>: Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: A revitalizing, long-lasting moisture treatment with the seductive scent of creamy Coconut, warm Madagascar Vanilla and sweet Amber leave your skin feeling soft + soothed.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN</strong>: Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT</strong>: The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST</strong>: Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$131-00-06$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned.</p><p>A revitalizing, long-lasting moisture treatment with the seductive scent of creamy Coconut, warm Madagascar Vanilla and sweet Amber leave your skin feeling soft + soothed.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN</strong>: Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: A revitalizing, long-lasting moisture treatment with the seductive scent of creamy Coconut, warm Madagascar Vanilla and sweet Amber leave your skin feeling soft + soothed.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN</strong>: Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT</strong>: The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST</strong>: Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$130-00-06$exseed$;
update public.media_kit_products set long_description = $exseed$Envelop your skin in a pampering, lightweight veil of Apricot Kernel oil and antioxidant-rich Pomegranate, Grape, Cranberry, Black Cumin and Carrot seed oils. Dry Oil delivers the same amount of moisture as your favorite lotion, without the extra weight. For instant hydration + a shimmering finish, spray lightly on your skin after bathing to lock in moisture. Skin will feel luxuriously soft and lightly scented with the energizing scent of Eucalyptus, Rosemary + Mint.$exseed$, updated_at = now() where part = $exseed$140-01-01$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>SULFATE FREE CLEANSER</strong>: Gently cleanse away dirt, oil, and makeup with a luxurious sulfate-free lather loaded with skin-loving botanicals and nutrient-rich ExSeed® Antioxidant Complex. Our moisturizing formula protects the skin’s natural moisture barrier with plant-based ingredients that condition as they clean and is so gentle you can even use it on your face!</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Fresh, crisp notes of Eucalyptus are surrounded by stimulating peppermint and a core of soothing Rosemary. A beautiful, spa-like fragrance that energizes your mind and invigorates your spirit.KEY INGREDIENTS: Shea butter, Coconut Oil, Vitamin E, and ExSeed®, our antioxidant blend of Cranberry, Carrot, Black Cumin, Grape, and Pomegranate seed oils.</li><li><strong>EXSEED® ANTIOXIDANT COMPLEX</strong>: ExSeed® combines sustainably sourced seed oils from Black Cumin, Cranberry, Raspberry, Grape, and Carrot seeds to replenish, moisturize and protect skin. These phytonutrient seed oils are extracted using a patented, cold-press process to preserve the powerful antioxidant benefits of the seeds for maximum skin benefits.</li><li><strong>100% FREE FROM</strong>: Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Fresh, crisp notes of Eucalyptus are surrounded by stimulating peppermint and a core of soothing Rosemary. A beautiful, spa-like fragrance that energizes your mind and invigorates your spirit.</li></ul>$exseed$, updated_at = now() where part = $exseed$100-00-01$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>DEEP LASTING HYDRATION</strong>: This nourishing hand + body lotion replenishes dry skin with rich, skin-loving moisture, leaving it soft, smooth + comfortably hydrated.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature antioxidant blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + restore dry, thirsty skin.</li><li><strong>COCONUT OIL + BOTANICAL OILS SOFTEN SKIN:</strong> Moisturizing coconut oil, shea butter + apricot kernel oil help smooth rough, dry areas and leave skin feeling supple + beautifully conditioned.</li><li><strong>SILKY, EVERYDAY MOISTURE:</strong> The luxurious lotion glides easily over skin and absorbs beautifully, delivering rich hydration without an overly heavy feel.</li><li><strong>HEAD-TO-TOE DRY SKIN CARE: </strong>Perfect for hands, arms, legs, elbows, knees + feet, this daily moisturizing lotion helps keep dry skin soft, smooth + cared for.</li><li><strong>BEAUTIFULLY SCENTED</strong>: Sparkling grapefruit, bergamot + citrus mingle with fresh marine notes, soft florals + warm woods for a clean, breezy fragrance that lingers lightly on skin.</li></ul>$exseed$, updated_at = now() where part = $exseed$110-00-05$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned.</p><p>A soothing, feel-good fragrance bursting with juicy orange and warm, invigorating ginger. Fresh citrus notes create an instant lift, while subtle lemongrass and citronella add a clean, finish that awakens your senses.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN</strong>: Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: A soothing, feel-good fragrance bursting with juicy orange and warm, invigorating ginger. Fresh citrus notes create an instant lift, while subtle lemongrass and citronella add a clean, finish that awakens your senses.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN</strong>: Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT</strong>: The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST</strong>: Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$130-00-09$exseed$;
update public.media_kit_products set long_description = $exseed$This beautiful acrylic display is designed to merchandise our Body + Face Dry Oils. The display holds 6 each of 4 fragrances (24 ea total).

Product must be ordered separately.

Envelop your skin in a pampering, lightweight veil of Apricot Kernel oil and antioxidant-rich Pomegranate, Grape, Cranberry, Black Cumin and Carrot seed oils. Dry Oil delivers the same amount of moisture as your favorite lotion, without the extra weight. For instant hydration and a shimmering finish, spray lightly on your skin after bathing to lock in moisture.$exseed$, updated_at = now() where part = $exseed$505-09-99$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Turn your daily shower into something a little more indulgent. Natural Inspirations Bath + Shower Gel creates a rich, botanical lather that gently cleanses without leaving skin feeling stripped or tight.</p><p>The sulfate-free formula is enriched with moisturizing shea butter, Vitamin E + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils to help condition skin as you cleanse. Skin is left feeling fresh, soft + comfortable with a light veil of fragrance. Aromatic lavender + sensual ylang mingle with bright citrus, soft florals + creamy sandalwood for a soothing, elegant fragrance with a warm finish.</p><p>Use as a luxurious daily body wash in the shower or add to running water for a fragrant, foaming bath. Follow with Natural Inspirations Hand + Body Lotion, Body Butter or Dry Body Oil for an extra layer of moisture.</p>$exseed$, benefits = $exseed$<ul><li><strong>GENTLY CLEANSES WITHOUT STRIPPING:</strong> Sulfate-free cleansing ingredients create a rich, satisfying lather that washes away everyday impurities while helping skin feel soft + comfortable.</li><li><strong>CLEAN, FRESH FRAGRANCE:</strong> Aromatic lavender + sensual ylang mingle with bright citrus, soft florals + creamy sandalwood for a soothing, elegant fragrance with a warm finish.[Fragrance-specific benefit]</li><li><strong>POWERED BY EXSEED®:</strong> Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils brings antioxidant-rich botanical nourishment to your daily cleansing ritual.</li><li><strong>SHEA BUTTER + VITAMIN E CONDITION SKIN:</strong> Moisturizing shea butter + Vitamin E help soften and condition skin while you cleanse.</li><li><strong>RICH, BOTANICAL LATHER:</strong> Creates a luxurious foam that glides easily over skin and transforms an everyday shower into a more indulgent body-care ritual.</li><li><strong>SHOWER GEL + BUBBLE BATH IN ONE:</strong> Use as a daily moisturizing body wash or pour under running water for a fragrant, foaming soak.</li></ul>$exseed$, updated_at = now() where part = $exseed$150-00-02$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned.</p><p>A revitalizing, long-lasting moisture treatment with the sparkling scent of citrus aloft sea breezes of marine, jasmine, sandalwood + amber leave your skin feeling soft and soothed.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN:</strong> Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE: </strong>Sparkling grapefruit, bergamot + citrus mingle with fresh marine notes, soft florals + warm woods for a clean, breezy fragrance that lingers lightly on skin.</li><li><strong>POWERED BY EXSEED®:</strong> Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN:</strong> Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT:</strong> The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST: </strong>Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$130-00-05$exseed$;
update public.media_kit_products set long_description = $exseed$Envelop your skin in a pampering, lightweight veil of Apricot Kernel oil and antioxidant-rich Pomegranate, Grape, Cranberry, Black Cumin and Carrot seed oils. Dry oil delivers the same amount of moisture as your favorite lotion, without the extra weight. For instant hydration + a shimmering finish, spray lightly on your skin after bathing to lock in moisture. Skin will feel luxuriously soft and lightly scented with the refreshing tang of ruby red Grapefruit + sweet juicy Bergamot.$exseed$, updated_at = now() where part = $exseed$140-01-04$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Wrap skin in a silky veil of nourishing botanical oils. Natural Inspirations Dry Body Oil is formulated with apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, grape, cranberry, black cumin + carrot seed oils to soften, condition and replenish dry skin.</p><p>The lightweight formula glides effortlessly over skin and absorbs beautifully without the heavy, greasy feel of traditional body oils. Massage onto damp skin after bathing to help lock in moisture, or smooth over dry skin anytime it needs extra softness + radiance.</p><p>Skin is left feeling luxuriously soft, smooth + lightly scented with Sea Salt Citrus—a sparkling blend of bright citrus, fresh marine notes, jasmine, sandalwood + warm amber.</p>$exseed$, benefits = $exseed$<ul><li><strong>SILKY MOISTURE + RADIANT SKIN:</strong> Nourishing body oil helps soften dry skin, replenish moisture + leave it smooth, supple and naturally glowing.</li><li><strong>SEA SALT CITRUS FRAGRANCE:</strong> Sparkling citrus mingles with fresh marine notes, jasmine, sandalwood + warm amber for a clean, breezy fragrance that lingers lightly on skin.</li><li><strong>POWERED BY EXSEED®: </strong>Our signature blend of cold-pressed pomegranate, grape, cranberry, black cumin + carrot seed oils delivers antioxidant-rich botanical nourishment for beautifully conditioned skin.</li><li><strong>APRICOT KERNEL OIL SOFTENS + CONDITIONS:</strong> Naturally emollient apricot kernel oil helps smooth dry, rough skin while supporting a soft, supple feel.</li><li><strong>FAST-ABSORBING + NEVER GREASY:</strong> This lightweight dry oil absorbs beautifully into skin, delivering silky moisture without a heavy or oily residue.</li><li><strong>MULTI-USE MOISTURE FOR BODY, FACE + HAIR:</strong> Use on the body to lock in moisture, smooth lightly over the face as desired, or apply sparingly to hair for added softness + shine.</li></ul>$exseed$, updated_at = now() where part = $exseed$140-00-05$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Turn your daily shower into something a little more indulgent. Natural Inspirations Bath + Shower Gel creates a rich, botanical lather that gently cleanses without leaving skin feeling stripped or tight.</p><p>The sulfate-free formula is enriched with moisturizing shea butter, Vitamin E + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils to help condition skin as you cleanse. Skin is left feeling fresh, soft and lightly scented with the soothing fragrance of crisp eucalyptus, fresh rosemary + stimulating peppermint.</p><p>Use as a luxurious daily body wash in the shower or add to running water for a fragrant, foaming bath. Follow with Natural Inspirations Hand + Body Lotion, Body Butter or Dry Body Oil for an extra layer of moisture.</p>$exseed$, benefits = $exseed$<strong>GENTLY CLEANSES WITHOUT STRIPPING:</strong> Sulfate-free cleansing ingredients create a rich, satisfying lather that washes away everyday impurities while helping skin feel soft + comfortable.<p><strong>CLEAN, FRESH FRAGRANCE:</strong> Refreshing eucalyptus, rosemary + cool mint blend with touches of citrus, lavender + soft woods for a fresh, aromatic scent that feels clean + invigorating.</p><p><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils brings antioxidant-rich botanical nourishment to your daily cleansing ritual.</p><p><strong>SHEA BUTTER + VITAMIN E CONDITION SKIN:</strong> Moisturizing shea butter + Vitamin E help soften and condition skin while you cleanse.</p><p><strong>RICH, BOTANICAL LATHER:</strong> Creates a luxurious foam that glides easily over skin and transforms an everyday shower into a more indulgent body-care ritual.</p><p><strong>SHOWER GEL + BUBBLE BATH IN ONE:</strong> Use as a daily moisturizing body wash or pour under running water for a fragrant, foaming soak.</p>$exseed$, updated_at = now() where part = $exseed$150-00-01$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned.</p><p>The delightfully crisp blend of Agave nectar, fresh Citrus and delicate Pear will leave your skin deliciously scented.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN</strong>: Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: The delightfully crisp blend of Agave nectar, fresh Citrus and delicate Pear will leave your skin deliciously scented.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN</strong>: Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT</strong>: The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST</strong>: Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$130-00-07$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for. Essential oils from crisp, ruby red grapefruit and sweet bergamot help refresh and rejuvenate and turn everyday hand care into a small moment of indulgence.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION</strong>: Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Crisp grapefruit + bright bergamot blend with sparkling citrus and soft musk for a fresh, uplifting fragrance that feels clean + rejuvenating.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN</strong>: Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE: </strong>This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDULGE DRY, HARDWORKING HANDS:</strong> Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$120-00-04$exseed$;
update public.media_kit_products set long_description = $exseed$Envelop your skin in a pampering, lightweight veil of Apricot Kernel oil and antioxidant-rich Pomegranate, Grape, Cranberry, Black Cumin + Carrot seed oils. Dry Oil delivers the same amount of moisture as your favorite lotion, without the extra weight. For instant hydration and a shimmering finish, spray lightly on your skin after bathing to lock in moisture. Skin will feel luxuriously soft and lightly scented with the purifying scent of Provence-inspired lavender + sensual ylang ylang.$exseed$, updated_at = now() where part = $exseed$140-01-02$exseed$;
update public.media_kit_products set long_description = $exseed$This rich, nutrient-packed formula delivers powerful hydration to hair and scalp with ExSeed ® Deep Moisturizing Complex, a nourishing combination of antioxidants including Pomegranate and Carrot seed oils to help moisturize and revitalize without weighing hair down.

Keratin protein penetrates deep, softening as it helps repair damage and reduce frizz leaving hair and scalp feeling healthy, strengthened, and deliciously scented with the warm, woody fragrance of Cypress, Fir, Eucalyptus and Citrus.$exseed$, updated_at = now() where part = $exseed$271-00-08$exseed$;
update public.media_kit_products set long_description = $exseed$Envelop your skin in a pampering, lightweight veil of Apricot Kernel oil + antioxidant-rich Pomegranate, Grape, Cranberry, Black Cumin and Carrot seed oils. Dry Oil delivers the same amount of moisture as your favorite lotion, without the extra weight. For instant hydration and a shimmering finish, spray lightly on your skin after bathing to lock in moisture. Skin will feel velvety smooth feel and deliciously scented with a seductive blend of creamy Coconut, warm Madagascar Vanilla + soft Amber.$exseed$, updated_at = now() where part = $exseed$140-01-06$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned.</p><p> A revitalizing, long-lasting moisture treatment with the sparkling scent of citrus aloft sea breezes of marine, jasmine, sandalwood + amber leave your skin feeling soft and soothed.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN:</strong> Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE:</strong> Crisp grapefruit + bright bergamot blend with sparkling citrus and soft musk for a fresh, uplifting fragrance that feels clean + rejuvenating.</li><li><strong>POWERED BY EXSEED®: </strong>Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN:</strong> Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT: </strong>The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST:</strong> Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$131-00-04$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>SULFATE FREE CLEANSER</strong>: Gently cleanse away dirt, oil, and makeup with a luxurious sulfate-free lather loaded with skin-loving botanicals and nutrient-rich ExSeed® Antioxidant Complex. Our moisturizing formula protects the skin’s natural moisture barrier with plant-based ingredients that condition as they clean and is so gentle you can even use it on your face!</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Discover the sparkling pure scent of Citrus aloft sea breezes of Marine and Jasmine. Sandalwood and Amber bring an earthy warmth, like sand between your toes. A fragrance that is joyful and fresh, like the sunshine on your face.</li><li><strong>KEY INGREDIENTS</strong>: Shea butter, Coconut Oil, Vitamin E, and ExSeed®, our antioxidant blend of Cranberry, Carrot, Black Cumin, Grape, and Pomegranate seed oils.</li><li><strong>EXSEED® ANTIOXIDANT COMPLEX</strong>: ExSeed® combines sustainably sourced seed oils from Black Cumin, Cranberry, Raspberry, Grape, and Carrot seeds to replenish, moisturize and protect skin. These phytonutrient seed oils are extracted using a patented, cold-press process to preserve the powerful antioxidant benefits of the seeds for maximum skin benefits.</li><li><strong>100% FREE FROM</strong>: Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$100-00-05$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned.</p><p>A revitalizing, long-lasting moisture treatment with the sparkling scent of citrus aloft sea breezes of marine, jasmine, sandalwood + amber leave your skin feeling soft and soothed.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN:</strong> Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE:</strong> Sparkling grapefruit, bergamot + citrus mingle with fresh marine notes, soft florals + warm woods for a clean, breezy fragrance that lingers lightly on skin.</li><li><strong>POWERED BY EXSEED®:</strong> Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN:</strong> Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT:</strong> The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST: </strong>Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$131-00-05$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>DEEP LASTING HYDRATION:</strong> This nourishing hand + body lotion replenishes dry skin with rich, skin-loving moisture, leaving it soft, smooth + comfortably hydrated.</li><li><strong>BEAUTIFULLY SCENTED</strong>: Creamy coconut + warm vanilla mingle with soft amber, sandalwood + delicate florals for a smooth, sophisticated fragrance with a cozy, sensual finish.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + restore dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN: </strong>Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry areas and leave skin feeling supple + beautifully conditioned.</li><li><strong>SILKY EVERYDAY MOISTURE:</strong> The luxurious lotion glides easily over skin and absorbs beautifully, delivering rich hydration without an overly heavy feel.</li><li><strong>HEAD TO TOE DRY SKIN CARE</strong>: Perfect for hands, arms, legs, elbows, knees + feet, this daily moisturizing lotion helps keep dry skin soft, smooth + cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$110-00-06$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Wrap skin in a silky veil of nourishing botanical oils. Natural Inspirations Dry Body Oil is formulated with apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, grape, cranberry, black cumin + carrot seed oils to soften, condition and replenish dry skin.</p><p>The lightweight formula glides effortlessly over skin and absorbs beautifully without the heavy, greasy feel of traditional body oils. Massage onto damp skin after bathing to help lock in moisture, or smooth over dry skin anytime it needs extra softness + radiance.</p><p>Skin is left feeling luxuriously soft, smooth + lightly scented with Provence-inspired lavender + sensual ylang mingled with bright citrus, soft florals + creamy sandalwood for a soothing, elegant fragrance with a warm finish.</p>$exseed$, benefits = $exseed$<ul><li><strong>SILKY MOISTURE + RADIANT SKIN</strong>: Nourishing body oil helps soften dry skin, replenish moisture + leave it smooth, supple and naturally glowing.</li><li><strong>CLEAN, FRESH FRAGRANCE</strong>: Provence-inspired lavender + sensual ylang mingle with bright citrus, soft florals + creamy sandalwood for a soothing, elegant fragrance with a warm finish.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, grape, cranberry, black cumin + carrot seed oils delivers antioxidant-rich botanical nourishment for beautifully conditioned skin.</li><li><strong>APRICOT KERNEL OIL SOFTENS + CONDITIONS</strong>: Naturally emollient apricot kernel oil helps smooth dry, rough skin while supporting a soft, supple feel.</li><li><strong>FAST-ABSORBING + NEVER GREASY</strong>: This lightweight dry oil absorbs beautifully into skin, delivering silky moisture without a heavy or oily residue.</li><li><strong>MULTI-USE MOISTURE FOR BODY, FACE + HAIR</strong>: Use on the body to lock in moisture, smooth lightly over the face as desired, or apply sparingly to hair for added softness + shine.</li></ul>$exseed$, updated_at = now() where part = $exseed$140-00-02$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for. </p><p>Creamy coconut + warm vanilla mingle with soft amber, sandalwood + delicate florals for a smooth, sophisticated fragrance with a cozy, sensual finish.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION</strong>: Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE: </strong>Creamy coconut + warm vanilla mingle with soft amber, sandalwood + delicate florals for a smooth, sophisticated fragrance with a cozy, sensual finish.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN</strong>: Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE</strong>: This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDULGE DRY, HARDWORKING HANDS:</strong> Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$121-00-06$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for.</p><p>A soothing, uplifting fragrance bursting with juicy orange and warm, invigorating ginger turns everyday hand care into a small moment of indulgence.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION:</strong> Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Sun-ripened orange + fresh lemon meet a warm hint of ginger for a bright, sparkling citrus fragrance that feels energizing + effortlessly fresh.</li><li><strong>POWERED BY EXSEED®:</strong> Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN: </strong>Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE: </strong>This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDULGE DRY, HARDWORKING HANDS:</strong> Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$120-00-09$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned. A revitalizing, long-lasting moisture treatment that will leave your skin feeling smooth, soft and lightly scented with essential oils from Provence-inspired lavender + sensual ylang.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN</strong>: Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Aromatic lavender + sensual ylang mingle with bright citrus, soft florals + creamy sandalwood for a soothing, elegant fragrance with a warm finish.</li><li><strong>POWERED BY EXSEED®: </strong>Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN: </strong>Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT:</strong> The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST:</strong> Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$131-00-02$exseed$;
update public.media_kit_products set long_description = $exseed$Wake up your senses and your skin with the purifying scent of zesty Orange + sparkling Ginger.

This creamy botanical wash gently cleanses hands + face, whisking away dirt, oil + makeup while keeping skin soft, balanced + happy. Blended with ExSeed®, our nurturing mix of cold-pressed seed oils—Pomegranate, Cranberry + Black Cumin—plus Shea Butter + Vitamin E, it pampers as it purifies, leaving skin fresh, hydrated + glowing.$exseed$, benefits = $exseed$<ul><li><strong>SULFATE FREE CLEANSER</strong>: Gently cleanse away dirt, oil, and makeup with a luxurious sulfate-free lather loaded with skin-loving botanicals and nutrient-rich ExSeed® Antioxidant Complex. Our moisturizing formula protects the skin’s natural moisture barrier with plant-based ingredients that condition as they clean and is so gentle you can even use it on your face!</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Orange and ginger create a fresh, spa-like blend that energizes the senses while promoting a sense of calm. Bright citrus uplifts the mood as warm ginger adds gentle clarity and balance.</li><li><strong>KEY INGREDIENTS</strong>: Shea butter, Coconut Oil, Vitamin E, and ExSeed®, our antioxidant blend of Cranberry, Carrot, Black Cumin, Grape, and Pomegranate seed oils.</li><li><strong>EXSEED® ANTIOXIDANT COMPLEX:</strong> ExSeed® combines sustainably sourced seed oils from Black Cumin, Cranberry, Raspberry, Grape, and Carrot seeds to replenish, moisturize and protect skin. These phytonutrient seed oils are extracted using a patented, cold-press process to preserve the powerful antioxidant benefits of the seeds for maximum skin benefits.</li><li><strong>100% FREE FROM</strong>: Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$100-00-09$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Indulge dry, thirsty skin with rich, concentrated moisture. Natural Inspirations Body Butter is an ultra-nourishing moisturizer formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>Its creamy, decadent texture melts into skin to help soften rough, dry areas and replenish lasting moisture without leaving skin feeling weighed down. Ideal for arms, legs, elbows, knees + anywhere skin needs extra care, it leaves skin feeling smooth, supple + deeply conditioned.</p><p>A soothing, feel-good fragrance bursting with juicy orange and warm, invigorating ginger. Fresh citrus notes create an instant lift, while subtle lemongrass and citronella add a clean, finish that awakens your senses.</p>$exseed$, benefits = $exseed$<ul><li><strong>INTENSE MOISTURE FOR DRY SKIN</strong>: Ultra-rich body butter delivers deep, concentrated hydration to help soften dry, rough skin and leave it feeling smooth, supple + comforted.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: A soothing, feel-good fragrance bursting with juicy orange and warm, invigorating ginger. Fresh citrus notes create an instant lift, while subtle lemongrass and citronella add a clean, finish that awakens your senses.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS NOURISH SKIN</strong>: Rich shea butter, coconut oil + apricot kernel oil help soften rough areas and restore a smoother, more conditioned feel.</li><li><strong>RICH, CREAMY + INDULGENT</strong>: The decadent texture melts into skin, delivering luxurious moisture without leaving it feeling overly heavy or greasy.</li><li><strong>EXTRA CARE WHERE SKIN NEEDS IT MOST</strong>: Ideal for arms, legs, elbows, knees + other dry areas, this deeply moisturizing body butter helps keep skin soft, smooth + beautifully cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$131-00-09$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for. </p><p>Creamy coconut + warm vanilla mingle with soft amber, sandalwood + delicate florals for a smooth, sophisticated fragrance with a cozy, sensual finish.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION</strong>: Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Creamy coconut + warm vanilla mingle with soft amber, sandalwood + delicate florals for a smooth, sophisticated fragrance with a cozy, sensual finish.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN:</strong> Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE: </strong>This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDULGE DRY, HARDWORKING HANDS: </strong>Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$120-00-06$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>DEEP LASTING HYDRATION:</strong> This nourishing hand + body lotion replenishes dry skin with rich, skin-loving moisture, leaving it soft, smooth + comfortably hydrated.</li><li><strong>BEAUTIFULLY SCENTED:</strong> Juicy pear + fresh citrus blend with crisp green notes, delicate florals + soft woods for a bright, refreshing fragrance with just a touch of sweetness.</li><li><strong>POWERED BY EXSEED®</strong>:Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + restore dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN:</strong> Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry areas and leave skin feeling supple + beautifully conditioned.</li><li><strong>SILKY EVERYDAY MOISTURE:</strong> The luxurious lotion glides easily over skin and absorbs beautifully, delivering rich hydration without an overly heavy feel.</li><li><strong>HEAD TO TOE DRY SKIN CARE:</strong> Perfect for hands, arms, legs, elbows, knees + feet, this daily moisturizing lotion helps keep dry skin soft, smooth + cared for.</li></ul>$exseed$, updated_at = now() where part = $exseed$110-00-07$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for. Essential oils from crisp eucalyptus, soothing rosemary and stimulating peppermint designed to turn everyday hand care into a small moment of indulgence.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION</strong>: Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE:</strong> Refreshing eucalyptus, rosemary + cool mint blend with touches of citrus, lavender + soft woods for a fresh, aromatic scent that feels clean + invigorating.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN</strong>: Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE</strong>: This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDLUGE DRY, HARDWORKING HANDS:</strong> Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$121-00-01$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>DEEP LASTING HYDRATION:</strong> This nourishing hand + body lotion replenishes dry skin with rich, skin-loving moisture, leaving it soft, smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE:</strong> Fresh, aromatic woods mingle with sophisticated green + earthy notes for a clean, modern fragrance that feels grounded, refined + subtly gender-neutral.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + restore dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN</strong>: Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry areas and leave skin feeling supple + beautifully conditioned.</li><li><strong>SILKY EVERYDAY MOISTURE: </strong>The luxurious lotion glides easily over skin and absorbs beautifully, delivering rich hydration without an overly heavy feel.</li><li><strong>HEAD TO TOE DRY SKIN CARE:</strong> Perfect for hands, arms, legs, elbows, knees + feet, this daily moisturizing lotion helps keep dry skin soft, smooth + cared for</li><li><strong>100% FREE FROM:</strong> Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$110-00-08$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for. Essential oils from Provence-inspired lavender and sensual ylang ylang help calm and soothe and turn everyday hand care into a small moment of indulgence.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION:</strong> Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE:</strong> Aromatic lavender + sensual ylang mingle with bright citrus, soft florals + creamy sandalwood for a soothing, elegant fragrance with a warm finish.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN:</strong> Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE: </strong>This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDULGE DRY, HARDWORKING HANDS:</strong> Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$121-00-02$exseed$;
update public.media_kit_products set long_description = $exseed$Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.<p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for. Essential oils from crisp, ruby red grapefruit and sweet bergamot help refresh and rejuvenate and turn everyday hand care into a small moment of indulgence.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION:</strong> Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE:</strong> Crisp grapefruit + bright bergamot blend with sparkling citrus and soft musk for a fresh, uplifting fragrance that feels clean + rejuvenating.</li><li><strong>POWERED BY EXSEED®:</strong> Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN:</strong> Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE:</strong> This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDLUGE DRY, HARDWORKING HANDS:</strong> Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$121-00-04$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for. </p><p>The delightfully crisp blend of Agave nectar, fresh Citrus and delicate Pear will leave your skin deliciously scented and turn everyday hand care into a small moment of indulgence.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION:</strong> Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE</strong>: Juicy pear + fresh citrus blend with crisp green notes, delicate florals + soft woods for a bright, refreshing fragrance with just a touch of sweetness.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN</strong>: Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE</strong>: This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDULGE DRY, HARDWORKING HANDS:</strong> Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$120-00-07$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for.</p><p>A sparkling scent of citrus aloft sea breezes of marine, jasmine, sandalwood and amber leave your skin soft, smooth + lightly fragranced, turning everyday hand care into a small moment of indulgence.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION:</strong> Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE:</strong> Sparkling grapefruit, bergamot + citrus mingle with fresh marine notes, soft florals + warm woods for a clean, breezy fragrance that lingers lightly on your skin.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN:</strong> Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE:</strong> This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDLUGE DRY, HARDWORKING HANDS:</strong> Ideal for frequent handwashing, dry weather + everyday use, this moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$121-00-05$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>DEEP LASTING HYDRATION: </strong>This nourishing hand + body lotion replenishes dry skin with rich, skin-loving moisture, leaving it soft, smooth + comfortably hydrated.</li><li><strong>POWERED BY EXSEED®:</strong> Our signature antioxidant blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + restore dry, thirsty skin.</li><li><strong>COCONUT OIL + BOTANICAL OILS SOFTEN SKIN: </strong>Moisturizing coconut oil, shea butter + apricot kernel oil help smooth rough, dry areas and leave skin feeling supple + beautifully conditioned.</li><li><strong>SILKY, EVERYDAY MOISTURE: </strong>The luxurious lotion glides easily over skin and absorbs beautifully, delivering rich hydration without an overly heavy feel.</li><li><strong>HEAD-TO-TOE DRY SKIN CARE: </strong>Perfect for hands, arms, legs, elbows, knees + feet, this daily moisturizing lotion helps keep dry skin soft, smooth + cared for.</li><li><strong>BEAUTIFULLY SCENTED: </strong>Refreshing eucalyptus, rosemary + cool mint blend with touches of citrus, lavender + soft woods for a fresh, aromatic scent that feels clean + invigorating.</li></ul>$exseed$, updated_at = now() where part = $exseed$110-00-01$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Wrap skin in a silky veil of nourishing botanical oils. Natural Inspirations Dry Body Oil is formulated with apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, grape, cranberry, black cumin + carrot seed oils to soften, condition and replenish dry skin.</p><p>The lightweight formula glides effortlessly over skin and absorbs beautifully without the heavy, greasy feel of traditional body oils. Massage onto damp skin after bathing to help lock in moisture, or smooth over dry skin anytime it needs extra softness + radiance.</p><p>Skin is left feeling luxuriously soft, smooth + deliciously scented with a seductive blend of creamy Coconut, warm Madagascar Vanilla + soft Amber.</p>$exseed$, benefits = $exseed$<ul><li><strong>SILKY MOISTURE + RADIANT SKIN:</strong> Nourishing body oil helps soften dry skin, replenish moisture + leave it smooth, supple and naturally glowing.</li><li><strong>CLEAN, FRESH FRAGRANCE:</strong> Creamy coconut + warm vanilla mingle with soft amber, sandalwood + delicate florals for a smooth, sophisticated fragrance with a cozy, sensual finish.</li><li><strong>POWERED BY EXSEED®:</strong> Our signature blend of cold-pressed pomegranate, grape, cranberry, black cumin + carrot seed oils delivers antioxidant-rich botanical nourishment for beautifully conditioned skin.</li><li><strong>APRICOT KERNEL OIL SOFTENS + CONDITIONS:</strong> Naturally emollient apricot kernel oil helps smooth dry, rough skin while supporting a soft, supple feel.</li><li><strong>FAST-ABSORBING + NEVER GREASY:</strong> This lightweight dry oil absorbs beautifully into skin, delivering silky moisture without a heavy or oily residue.</li><li><strong>MULTI-USE MOISTURE FOR BODY, FACE + HAIR:</strong> Use on the body to lock in moisture, smooth lightly over the face as desired, or apply sparingly to hair for added softness + shine.</li></ul>$exseed$, updated_at = now() where part = $exseed$140-00-06$exseed$;
update public.media_kit_products set long_description = $exseed$Slip into softness and glowing skin with the uplifting scent of zesty Orange + sparkling Ginger.

This silky, ultra-hydrating lotion melts effortlessly into skin to comfort dryness + restore natural radiance. Enriched with ExSeed®, our nurturing blend of cold-pressed seed oils—Pomegranate, Cranberry + Black Cumin—plus Shea Butter + Coconut Oil, it leaves skin smooth, soothed + deeply nourished — nature’s touch in every drop.$exseed$, benefits = $exseed$<ul><li><strong>DEEP LASTING HYDRATION: </strong>This nourishing hand + body lotion replenishes dry skin with rich, skin-loving moisture, leaving it soft, smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE: </strong>Sun-ripened orange + fresh lemon meet a warm hint of ginger for a bright, sparkling citrus fragrance that feels energizing + effortlessly fresh.</li><li><strong>POWERED BY EXSEED®: </strong>Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + restore dry, thirsty skin.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN: </strong>Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry areas and leave skin feeling supple + beautifully conditioned.</li><li><strong>SILKY EVERYDAY MOISTURE:</strong> The luxurious lotion glides easily over skin and absorbs beautifully, delivering rich hydration without an overly heavy feel.</li><li><strong>HEAD TO TOE DRY SKIN CARE:</strong> Perfect for hands, arms, legs, elbows, knees + feet, this daily moisturizing lotion helps keep dry skin soft, smooth + cared for</li><li><strong>100% FREE FROM:</strong> Parabens, Sulfates, Phthalates, Synthetic Dyes, Propylene Glycol, EDTA, PEGs, Triclosan, Formaldehyde, Silicones. 100% Vegan, Gluten-Free and Made in USA.</li></ul>$exseed$, updated_at = now() where part = $exseed$110-00-09$exseed$;
update public.media_kit_products set benefits = $exseed$<ul><li><strong>DEEP LASTING HYDRATION</strong>: This nourishing hand + body lotion replenishes dry skin with rich, skin-loving moisture, leaving it soft, smooth + comfortably hydrated.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature antioxidant blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + restore dry, thirsty skin.</li><li><strong>COCONUT OIL + BOTANICAL OILS SOFTEN SKIN</strong>: Moisturizing coconut oil, shea butter + apricot kernel oil help smooth rough, dry areas and leave skin feeling supple + beautifully conditioned.</li><li><strong>SILKY, EVERYDAY MOISTURE</strong>: The luxurious lotion glides easily over skin and absorbs beautifully, delivering rich hydration without an overly heavy feel.</li><li><strong>HEAD-TO-TOE DRY SKIN CARE</strong>: Perfect for hands, arms, legs, elbows, knees + feet, this daily moisturizing lotion helps keep dry skin soft, smooth + cared for.</li><li><strong>BEAUTIFULLY SCENTED</strong>: Refreshing eucalyptus, rosemary + cool mint blend with touches of citrus, lavender + soft woods for a fresh, aromatic scent that feels clean + invigorating.</li></ul>$exseed$, updated_at = now() where part = $exseed$110-00-02$exseed$;
update public.media_kit_products set long_description = $exseed$<p>Give dry, hardworking hands the moisture they crave. Natural Inspirations Hand Crème is a rich, luxurious moisturizing hand cream formulated with shea butter, coconut oil, apricot kernel oil + our signature ExSeed® blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils.</p><p>The nourishing formula helps soften rough, dry skin and restore lasting moisture while absorbing beautifully for a smooth, silky finish that never feels overly heavy or greasy. Perfect for frequent handwashing, dry weather + everyday use, it leaves hands feeling soft, conditioned + cared for.</p><p>An intoxicating scent of fresh cypress, eucalyptus + crisp fir leave your skin soft, smooth + deliciously fragranced.</p>$exseed$, benefits = $exseed$<ul><li><strong>DEEP, LASTING HYDRATION:</strong> Rich, nourishing hand crème delivers concentrated moisture to help soften dry, rough hands and leave skin feeling smooth + comfortably hydrated.</li><li><strong>CLEAN FRESH FRAGRANCE: </strong>Fresh, aromatic woods mingle with sophisticated green + earthy notes for a clean, modern fragrance that feels grounded, refined + subtly gender-neutral.</li><li><strong>POWERED BY EXSEED®</strong>: Our signature blend of cold-pressed pomegranate, cranberry, grape, carrot + black cumin seed oils helps nourish, condition + replenish dry, hardworking hands.</li><li><strong>SHEA BUTTER + BOTANICAL OILS SOFTEN SKIN:</strong> Moisturizing shea butter, coconut oil + apricot kernel oil help smooth rough, dry skin and leave hands feeling supple + beautifully conditioned.</li><li><strong>RICH MOISTURE WITHOUT THE GREASE:</strong> This luxurious hand cream absorbs beautifully, delivering intensive moisture with a silky finish that feels soft + smooth, never heavy or greasy.</li><li><strong>MADE TO INDULGE DRY, HARDWORKING HANDS</strong>: Ideal for frequent handwashing, dry weather + everyday use, this ultra-moisturizing hand crème helps keep hands soft, smooth + cared for throughout the day.</li></ul>$exseed$, updated_at = now() where part = $exseed$120-00-08$exseed$;
